from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from .api.routes import router
from .api.signals import router as signals_router
from .api.live import router as live_router
from .db import init_db

app=FastAPI(title="Qanas Data Engine",version="0.5.0")
@app.on_event("startup")
def startup(): init_db()
app.include_router(router,prefix="/api")
app.include_router(signals_router,prefix="/api")
app.include_router(live_router,prefix="/api")

DASHBOARD_HTML=r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>قنص · QANAS</title><style>
:root{--bg:#05090d;--panel:#0a1118;--line:#182633;--text:#f4f6f7;--muted:#71808c;--gold:#d9b76d;--green:#42d392;--cyan:#58bce8;--amber:#f2a94b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#172116 0,transparent 25%),var(--bg);color:var(--text);font-family:Segoe UI,Tahoma,Arial}.wrap{max-width:1900px;margin:auto;padding:22px}.top,.toolbar,.actions,.chips{display:flex;gap:10px;align-items:center}.top{justify-content:space-between;margin-bottom:18px}.brand{display:flex;gap:13px;align-items:center}.mark{width:50px;height:50px;border:1px solid #80683b;border-radius:12px;display:grid;place-items:center;font-size:24px;color:var(--gold);font-weight:900;background:#11150f}.brand h1{margin:0;font-size:24px}.muted,.company{color:var(--muted)}.btn,.chip{border:1px solid var(--line);background:#0a1219;color:var(--text);padding:10px 14px;border-radius:9px;cursor:pointer}.btn.gold,.chip.active{border-color:#9a7d46;background:linear-gradient(135deg,#e2c47f,#b6924e);color:#090a08;font-weight:800}.hero{display:grid;grid-template-columns:1.55fr .45fr;gap:12px;margin-bottom:12px}.hero>div,.stat{border:1px solid var(--line);background:linear-gradient(145deg,#0d161e,#080f15);border-radius:13px;padding:18px}.hero h2{font-size:31px;margin:5px 0 8px}.syncrow{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #14212b}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin-bottom:12px}.stat{padding:14px 16px;border-right:2px solid #80683b}.stat span{font-size:11px;color:var(--muted)}.stat b{display:block;font-size:22px;margin-top:5px}.toolbar{justify-content:space-between;border:1px solid var(--line);background:#080f15;padding:9px;border-radius:12px 12px 0 0;overflow:auto;position:sticky;top:0;z-index:20}.search{min-width:250px;flex:1}.search input{width:100%;background:#050b10;border:1px solid #1b2a35;color:white;border-radius:8px;padding:10px 12px}.chips{white-space:nowrap}.chip{padding:8px 11px;font-size:12px}.tablebox{border:1px solid var(--line);border-top:0;overflow:auto;background:#070d12}table{width:100%;border-collapse:separate;border-spacing:0;min-width:1650px;font-variant-numeric:tabular-nums}th,td{padding:10px 11px;border-bottom:1px solid #13202a;text-align:right;white-space:nowrap}th{font-size:10px;color:#6e818e;background:#091119;position:sticky;top:55px;z-index:10}tbody tr{cursor:pointer}tbody tr:hover{background:#101b23}.ticker{font-size:15px;font-weight:900}.company{font-size:10px;max-width:155px;overflow:hidden;text-overflow:ellipsis}.good,.rise,.live{color:var(--green);font-weight:800}.nearready{color:var(--amber);font-weight:800}.goldtext{color:var(--gold);font-weight:800}.rebate{color:var(--cyan);font-weight:800}.pill{border:1px solid #263947;padding:4px 7px;border-radius:6px}.readybadge{display:inline-flex;padding:5px 9px;border-radius:7px;font-weight:900}.ready100{background:#123026;color:#5be0a5;border:1px solid #285944}.ready90{background:#322514;color:#ffc468;border:1px solid #624724}.ready80{background:#292419;color:#d7b66d;border:1px solid #504329}.progress{width:74px;height:3px;background:#1a2730;border-radius:5px;margin-top:5px;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),var(--green))}.empty{text-align:center;padding:50px;color:var(--muted)}.drawer{position:fixed;inset:0;background:#000b;display:none;z-index:50}.drawer.open{display:block}.sheet{position:absolute;left:0;top:0;height:100%;width:min(570px,94vw);background:#071017;border-right:1px solid #263744;padding:25px;overflow:auto}.close{float:left;background:#101b23;border:1px solid var(--line);border-radius:8px;color:white;font-size:22px;width:38px;height:38px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:15px}.mini{background:#0a141c;border:1px solid var(--line);border-radius:9px;padding:12px}.mini span{display:block;color:var(--muted);font-size:10px;margin-bottom:5px}.histrow{display:grid;grid-template-columns:1.3fr .8fr .8fr .8fr;gap:8px;padding:9px;border-bottom:1px solid var(--line);font-size:12px}.toast{position:fixed;bottom:20px;right:20px;background:#102019;padding:12px;border:1px solid #31553f;border-radius:9px;display:none}.toast.show{display:block}@media(max-width:900px){.wrap{padding:12px}.hero{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column}}
</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="mark">ق</div><div><h1>قنص</h1><small class="muted">QANAS · REVERSE SPLIT INTELLIGENCE</small></div></div><div class="actions"><button class="btn" onclick="loadData()">↻ تحديث العرض</button><button id="borrowBtn" class="btn gold" onclick="startBorrowSync()">تحديث Available + CTB + Rebate</button></div></div><section class="hero"><div><div class="goldtext">QANAS TERMINAL / LIVE</div><h2>القنص بالركادة.</h2><p class="muted">لوحة واحدة لقراءة الندرة، القاع، الثبات، الجاهزية والانطلاق.</p></div><div><div class="syncrow"><span class="muted">حالة المحرك</span><strong id="syncState" class="good">متصل</strong></div><div class="syncrow"><span class="muted">آخر Borrow</span><strong id="lastBorrow">—</strong></div><div class="syncrow"><span class="muted">السعر</span><strong class="live">LIVE · يشمل الممتد</strong></div></div></section><section class="stats"><div class="stat"><span>الأسهم الفعالة</span><b id="sTotal">—</b></div><div class="stat"><span>AVAILABLE ≤ 10K</span><b id="sScarce">—</b></div><div class="stat"><span>وصلت النصف</span><b id="sHalf">—</b></div><div class="stat"><span>قريبة من القاع ≤10%</span><b id="sNear">—</b></div><div class="stat"><span>🎯 الجاهزة والقريبة</span><b id="sReady">—</b></div></section><div class="toolbar"><div class="search"><input id="q" placeholder="ابحث بالرمز أو الشركة..." oninput="render()"></div><div class="chips"><button class="chip active" onclick="setFilter('all',this)">كل السوق</button><button class="chip" onclick="setFilter('ready',this)">🎯 الأجهز</button><button class="chip" onclick="setFilter('launched',this)">🚀 انطلقت +40%</button><button class="chip" onclick="setFilter('scarce',this)">Available منخفض</button><button class="chip" onclick="setFilter('near',this)">قريب من القاع</button><button class="chip" onclick="setFilter('half',this)">وصل النصف</button></div></div><div class="tablebox"><table><thead><tr><th>السهم</th><th>الجاهزية</th><th>Available</th><th>CTB</th><th>Rebate</th><th>السعر LIVE</th><th>القاع</th><th>عن القاع</th><th>القمة</th><th>النصف</th><th>الثبات</th><th>بعد الجاهزية</th><th>وش باقي؟</th><th>التاريخ</th><th>التقسيم</th></tr></thead><tbody id="rows"></tbody></table></div></div><div id="drawer" class="drawer" onclick="if(event.target===this)closeDrawer()"><div class="sheet"><button class="close" onclick="closeDrawer()">×</button><div id="detail"></div></div></div><div id="toast" class="toast"></div><script>
let data=[],signals={},live={},filter='all';const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:2}),money=n=>n==null?'—':'$'+Number(n).toFixed(4),pct=n=>n==null?'—':Number(n).toFixed(2)+'%';function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3000)}function setFilter(f,e){filter=f;document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));e.classList.add('active');render()}async function loadData(){try{syncState.textContent='يتم التحديث...';const [d,s,l]=await Promise.all([fetch('/api/hunt').then(r=>r.json()),fetch('/api/signals').then(r=>r.json()),fetch('/api/live-prices').then(r=>r.json())]);signals=Object.fromEntries(s.map(x=>[x.symbol,x]));live=Object.fromEntries(l.map(x=>[x.symbol,x]));data=d.map(x=>({...x,signal:signals[x.symbol]||null,live:live[x.symbol]||null}));syncState.textContent='متصل';summary();render()}catch(e){syncState.textContent='خطأ اتصال'}}function summary(){sTotal.textContent=data.length;sScarce.textContent=data.filter(x=>x.available!=null&&x.available<=10000).length;sHalf.textContent=data.filter(x=>x.half_level_reached).length;sNear.textContent=data.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10).length;sReady.textContent=data.filter(x=>x.signal?.ready||x.signal?.near_ready).length;const d=data.map(x=>x.borrow_timestamp).filter(Boolean).sort().pop();lastBorrow.textContent=d?new Date(d+'Z').toLocaleString('ar-SA'):'—'}function rank(x){return x.signal?.ready?100:Number(x.signal?.readiness_pct??x.ready_score??0)}function render(){let a=data,q=document.getElementById('q').value.trim().toUpperCase();a=a.filter(x=>!q||x.symbol.includes(q)||(x.company||'').toUpperCase().includes(q));if(filter==='scarce')a=a.filter(x=>x.available!=null&&x.available<=10000);if(filter==='half')a=a.filter(x=>x.half_level_reached);if(filter==='near')a=a.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10);if(filter==='ready')a=a.filter(x=>x.signal?.ready||x.signal?.near_ready);if(filter==='launched')a=a.filter(x=>x.signal?.launched);a.sort((a,b)=>filter==='launched'?(b.signal?.rise_pct||0)-(a.signal?.rise_pct||0):filter==='ready'?(rank(b)-rank(a)||((a.available??1e12)-(b.available??1e12))||((a.distance_from_low_pct??1e9)-(b.distance_from_low_pct??1e9))):(b.ready_score||0)-(a.ready_score||0));rows.innerHTML=a.length?a.map(x=>{let s=x.signal,dt=s?.launched_at||s?.ready_at,lp=x.live?.live_price,shown=lp??x.current_price,r=rank(x),status=s?.ready?'100% 🎯':s?.near_ready?`${fmt(r)}%`:'—',cls=r>=100?'ready100':r>=90?'ready90':'ready80',missing=s?.ready?'مكتمل ✓':s?.missing||'—';return `<tr onclick="openStock('${x.symbol}')"><td><b class="ticker">${x.symbol}</b><div class="company">${x.company||''}</div></td><td>${s?.ready||s?.near_ready?`<span class="readybadge ${cls}">${status}</span><div class="progress"><i style="width:${Math.min(100,r)}%"></i></div>`:`<span class="company">سكور ${fmt(x.ready_score)}</span>`}</td><td class="${x.available<=10000?'good':''}">${fmt(x.available)}</td><td class="goldtext">${pct(x.ctb)}</td><td class="rebate">${pct(x.rebate_rate)}</td><td class="${lp!=null?'live':''}">${money(shown)}<div class="company">${lp!=null?'LIVE · ممتد':'آخر إغلاق'}</div></td><td>${money(x.post_split_low)}</td><td>${pct(x.distance_from_low_pct)}</td><td>${money(x.post_split_high)}</td><td><span class="pill">${money(x.half_level)} ${x.half_level_reached?'✓':''}</span></td><td>${fmt(x.stability_sessions)} / 4</td><td class="rise">${s?.rise_pct!=null?pct(s.rise_pct):'—'}</td><td class="${s?.near_ready?'nearready':''}">${missing}</td><td>${dt?new Date(dt+'Z').toLocaleDateString('ar-SA'):'—'}<div class="company">${s?.launched?'🚀 انطلق':s?.ready?'🎯 جاهز':s?.near_ready?'قريب جدًا':''}</div></td><td>${x.ratio}<div class="company">${x.effective_date}</div></td></tr>`}).join(''):'<tr><td colspan="15" class="empty">لا توجد نتائج</td></tr>'}async function openStock(symbol){drawer.classList.add('open');detail.innerHTML='<div class="empty">جاري التحميل...</div>';try{const [s,h]=await Promise.all([fetch('/api/stock/'+symbol).then(r=>r.json()),fetch('/api/borrow/'+symbol+'/history?limit=12').then(r=>r.json())]),g=signals[symbol],l=live[symbol];detail.innerHTML=`<div class="goldtext">QANAS / STOCK INTELLIGENCE</div><h2 style="font-size:34px;margin-bottom:2px">${s.symbol}</h2><div class="muted">${s.company||''}</div>${g?.near_ready?`<div class="mini nearready" style="margin-top:16px"><span>وش باقي للجاهزية؟</span><b>${g.missing}</b></div>`:''}${g?.strength?`<div class="mini good" style="margin-top:9px"><span>نقاط القوة</span><b>${g.strength}</b></div>`:''}<div class="grid2"><div class="mini"><span>السعر الحالي · الممتد</span><b class="live">${money(l?.live_price??s.current_price)}</b></div><div class="mini"><span>آخر إغلاق يومي</span><b>${money(s.current_price)}</b></div><div class="mini"><span>Available</span><b>${fmt(s.available)}</b></div><div class="mini"><span>CTB</span><b class="goldtext">${pct(s.ctb)}</b></div><div class="mini"><span>Rebate</span><b class="rebate">${pct(s.rebate_rate)}</b></div><div class="mini"><span>عن القاع</span><b>${pct(s.distance_from_low_pct)}</b></div><div class="mini"><span>الثبات</span><b>${fmt(s.stability_sessions)} / 4</b></div><div class="mini"><span>مستوى النصف</span><b>${money(s.half_level)} ${s.half_level_reached?'✓':''}</b></div><div class="mini"><span>ارتفاع بعد الجاهزية</span><b class="rise">${g?.rise_pct!=null?pct(g.rise_pct):'—'}</b></div><div class="mini"><span>أعلى ارتفاع 4H</span><b>${pct(s.four_hour_highest_rise_pct)}</b></div></div><h3>آخر قراءات الاقتراض</h3>${h.map(r=>`<div class="histrow"><span>${new Date(r.timestamp+'Z').toLocaleString('ar-SA')}</span><b>${fmt(r.available)}</b><b>${pct(r.ctb)}</b><b class="rebate">${pct(r.rebate_rate)}</b></div>`).join('')}`}catch(e){detail.innerHTML='تعذر التحميل'}}function closeDrawer(){drawer.classList.remove('open')}async function startBorrowSync(){borrowBtn.disabled=true;await fetch('/api/sync/borrow/all');pollBorrow()}async function pollBorrow(){const s=await fetch('/api/sync/borrow/status').then(r=>r.json());borrowBtn.textContent=s.running?`تحديث ${s.processed}/${s.total}`:'تحديث Available + CTB + Rebate';if(s.running)setTimeout(pollBorrow,1500);else{borrowBtn.disabled=false;toast('اكتمل التحديث');loadData()}}loadData();setInterval(loadData,60000);
</script></body></html>'''
@app.get('/',response_class=HTMLResponse)
def dashboard(): return HTMLResponse(DASHBOARD_HTML)
